// ── Hover button ─────────────────────────────────────────────────────────────
const Btn = ({ children, onClick, variant="primary", small, full, disabled, style:extraStyle }) => {
  const [hov, setHov] = useState(false);
  const base = {
    primary:  { bg: C.pru,     bgH: C.pruDark, color: C.white,   border:"none" },
    secondary:{ bg:"transparent", bgH:"#EEECEA", color: C.navy,  border:`1.5px solid ${C.border}` },
    ghost:    { bg:"transparent", bgH: C.pruLight, color: C.pru, border:`1.5px solid ${C.pru}` },
    success:  { bg: C.teal,    bgH:"#158A62",  color: C.white,   border:"none" },
    gold:     { bg: C.gold,    bgH:"#A87E22",  color: C.white,   border:"none" },
    dark:     { bg: C.navyMid, bgH: C.navy,    color: C.white,   border:"none" },
    white:    { bg: C.white,   bgH:"#F1EFE8",  color: C.navy,    border:`1px solid ${C.border}` },
  }[variant] || {};
  return (
    <button
      onClick={onClick} disabled={disabled}
      onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{
        background: hov ? base.bgH : base.bg,
        color: base.color, border: base.border,
        padding: small ? "6px 14px" : "11px 24px",
        borderRadius: 9, fontSize: small ? 12 : 14,
        fontWeight: 700, cursor: disabled ? "not-allowed":"pointer",
        opacity: disabled ? 0.5 : 1,
        width: full ? "100%" : undefined,
        transition: "background 0.18s, transform 0.12s, box-shadow 0.15s",
        transform: hov && !disabled ? "translateY(-1px)" : "none",
        boxShadow: hov && !disabled ? "0 4px 12px rgba(0,0,0,0.18)" : "none",
        fontFamily:"inherit", ...extraStyle,
      }}
    >{children}</button>
  );
};

// ── Badge ────────────────────────────────────────────────────────────────────
const Badge = ({ children, color="default" }) => {
  const map={default:{bg:"#F1EFE8",text:"#5F5E5A"},success:{bg:"#E1F5EE",text:"#0F6E56"},warning:{bg:"#FAEEDA",text:"#854F0B"},danger:{bg:"#FCEBEB",text:"#A32D2D"},info:{bg:"#E6F1FB",text:"#185FA5"},pru:{bg:"#FDECEA",text:"#A8121F"}};
  const s=map[color]||map.default;
  return <span style={{background:s.bg,color:s.text,fontSize:11,fontWeight:600,padding:"2px 9px",borderRadius:20,whiteSpace:"nowrap",letterSpacing:0.3}}>{children}</span>;
};

// ── MetricCard ───────────────────────────────────────────────────────────────
const MetricCard = ({ label, value, sub, accent=C.pru }) => (
  <div style={{background:C.white,border:`1px solid ${C.border}`,borderRadius:14,padding:"18px 20px",position:"relative",overflow:"hidden"}}>
    <div style={{position:"absolute",top:0,left:0,width:4,height:"100%",background:accent,borderRadius:"14px 0 0 14px"}}/>
    <div style={{paddingLeft:8}}>
      <div style={{fontSize:11,color:C.muted,fontWeight:500,marginBottom:4,textTransform:"uppercase",letterSpacing:0.8}}>{label}</div>
      <div style={{fontSize:26,fontWeight:700,color:C.navy,lineHeight:1}}>{value}</div>
      {sub&&<div style={{fontSize:12,color:C.slate,marginTop:4}}>{sub}</div>}
    </div>
  </div>
);

// ── MiniBar ──────────────────────────────────────────────────────────────────
const MiniBar = ({ data, colors }) => {
  const max=Math.max(...data.map(d=>d.value));
  return (
    <div>
      {data.map((d,i)=>(
        <div key={i} style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
          <div style={{width:100,fontSize:12,color:C.slate,textAlign:"right",flexShrink:0}}>{d.label}</div>
          <div style={{flex:1,background:"#F1EFE8",borderRadius:4,overflow:"hidden",height:18}}>
            <div style={{width:`${(d.value/max)*100}%`,background:colors[i%colors.length],height:"100%",borderRadius:4,display:"flex",alignItems:"center",justifyContent:"flex-end",paddingRight:4}}>
              {d.value>3&&<span style={{fontSize:10,color:C.white,fontWeight:700}}>{d.value}</span>}
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

// ── Carousel ─────────────────────────────────────────────────────────────────
const Carousel = ({ images, height=480, overlay=true }) => {
  const [cur,setCur]=useState(0);
  useEffect(()=>{
    const t=setInterval(()=>setCur(p=>(p+1)%images.length),4500);
    return ()=>clearInterval(t);
  },[images.length]);
  return (
    <div style={{position:"relative",height,overflow:"hidden",borderRadius:0}}>
      {images.map((img,i)=>(
        <div key={i} style={{position:"absolute",inset:0,transition:"opacity 1s ease",opacity:cur===i?1:0}}>
          <img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
        </div>
      ))}
      {overlay&&<div style={{position:"absolute",inset:0,background:"linear-gradient(to right, rgba(10,22,40,0.82) 0%, rgba(10,22,40,0.45) 60%, rgba(10,22,40,0.2) 100%)"}}/>}
      <div style={{position:"absolute",bottom:16,left:"50%",transform:"translateX(-50%)",display:"flex",gap:6}}>
        {images.map((_,i)=>(
          <button key={i} onClick={()=>setCur(i)} style={{width:i===cur?24:8,height:8,borderRadius:4,background:i===cur?"white":"rgba(255,255,255,0.45)",border:"none",cursor:"pointer",transition:"width 0.3s"}}/>
        ))}
      </div>
    </div>
  );
};

