const AuthLayout = ({img, title, sub, accent, icon, children}) => (
  <div style={{minHeight:"100vh",display:"grid",gridTemplateColumns:"1fr 1fr"}}>
    <div style={{position:"relative",overflow:"hidden"}}>
      <img src={img} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
      <div style={{position:"absolute",inset:0,background:"linear-gradient(135deg,rgba(10,22,40,0.8),rgba(10,22,40,0.5))"}}/>
      <div style={{position:"absolute",inset:0,display:"flex",flexDirection:"column",justifyContent:"flex-end",padding:40}}>
        <div style={{width:48,height:48,background:accent,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"center",fontSize:24,marginBottom:16}}>{icon}</div>
        <h2 style={{color:C.white,fontSize:28,margin:0,fontWeight:800}}>SHIELD</h2>
        <p style={{color:"rgba(255,255,255,0.6)",margin:"8px 0 0",fontSize:14}}>Community-Based Health Insurance Platform; Prudential Uganda</p>
      </div>
    </div>
    <div style={{display:"flex",alignItems:"center",justifyContent:"center",background:C.bg,padding:40}}>
      <div style={{background:C.white,borderRadius:20,padding:"44px 40px",width:"100%",maxWidth:400,boxShadow:"0 8px 40px rgba(0,0,0,0.08)"}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <div style={{width:52,height:52,background:accent,borderRadius:12,display:"flex",alignItems:"center",justifyContent:"center",margin:"0 auto 14px",fontSize:24}}>{icon}</div>
          <h2 style={{color:C.navy,fontSize:20,margin:0}}>{title}</h2>
          <p style={{color:C.muted,fontSize:13,marginTop:6}}>{sub}</p>
        </div>
        {children}
      </div>
    </div>
  </div>
);

const AuthField = ({label,value,onChange,placeholder,type="text",onEnter}) => (
  <div style={{marginBottom:16}}>
    <label style={{fontSize:11,fontWeight:700,color:C.slate,display:"block",marginBottom:5,textTransform:"uppercase",letterSpacing:0.5}}>{label}</label>
    <input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}
      onKeyDown={e=>e.key==="Enter"&&onEnter&&onEnter()}
      style={{width:"100%",padding:"11px 14px",borderRadius:8,border:`1px solid ${C.border}`,fontSize:14,boxSizing:"border-box",outline:"none",fontFamily:"inherit"}}/>
  </div>
);

// ── PRUDENTIAL ADMIN DASHBOARD ────────────────────────────────────────────────
const AdminDashboard = ({ setPage }) => {
  const [activeCbhi,setActiveCbhi]=useState("kivulu");
  const [activeTab,setActiveTab]=useState("overview");
  const [expandedChart,setExpandedChart]=useState(null);
  const tabs=["overview","maps & analytics","members","claims","cbhi management"];

  const chartInfo={
    risk:{detail:"57 of 58 surveyed households in Makerere Kivulu were classified as High Risk, with only 2 falling into Moderate Risk. This was driven by the combined weight of high illness frequency, financial vulnerability, poor healthcare access in parts of the community, and medical financial burden. This distribution was central to justifying the need for community-based risk pooling through CBHI."},
    vulnerability:{detail:"The majority of Kivulu households (41 of 58) fall into Medium Vulnerability; financially fragile but not destitute. 4 households are highly vulnerable. Only 14 show low vulnerability. This middle band is the primary target for CBHI, as these households can potentially contribute to savings schemes but cannot sustain individual insurance premiums of UGX 1,000,000 or above."},
    illness:{detail:"48 households experienced frequent illness; defined as more than 2 episodes in the past 3 months or the presence of a chronic condition. Only 6 had rare illness events. This high burden of frequent illness creates recurring, unpredictable healthcare expenditure that out-of-pocket payment cannot sustainably absorb."},
    access:{detail:"Healthcare access across Kivulu is nearly evenly split: 20 households have good access (within 0.76 to 1.72 km of a facility), 19 have moderate access (1.72 to 2.07 km), and 20 have relatively poor access (beyond 2.07 km). The main facility serving the community is the Seventh-Day Adventist Health Facility at the northern edge of the study area."},
    income:{detail:"59% of Kivulu households depend on business income (trade, petty commerce), while 20% rely on casual and daily wage labour. Only 7% are formally salaried. This income structure means most households face significant income irregularity; making lump-sum insurance payments difficult and reinforcing the need for a structured savings model like Engabo."},
    payment:{detail:"77% of households pay for healthcare out of pocket with no savings buffer. 14% borrow money when illness strikes. Only 9% draw on savings. This pattern reveals extreme financial exposure; a single serious illness can trigger debt spirals. It provides the clearest possible justification for introducing a pooled health financing mechanism."},
  };

  return (
    <div style={{minHeight:"100vh",background:C.bg,fontFamily:"sans-serif",display:"flex"}}>
      {/* Sidebar */}
      <aside style={{width:220,background:C.navyMid,flexShrink:0,display:"flex",flexDirection:"column",position:"sticky",top:0,height:"100vh",overflowY:"auto"}}>
        <div style={{padding:"20px 16px 16px",borderBottom:"1px solid rgba(255,255,255,0.08)"}}>
          <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:4}}>
            <div style={{width:28,height:28,background:C.pru,borderRadius:6,display:"flex",alignItems:"center",justifyContent:"center"}}>
              <svg width={14} height={14} viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth={2}><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
            </div>
            <span style={{color:C.white,fontWeight:700,fontSize:14}}>SHIELD</span>
          </div>
          <div style={{fontSize:10,color:"rgba(255,255,255,0.4)",textTransform:"uppercase",letterSpacing:1}}>Prudential Portal</div>
        </div>
        <div style={{padding:"12px 8px"}}>
          <div style={{fontSize:10,color:"rgba(255,255,255,0.35)",textTransform:"uppercase",letterSpacing:1,padding:"4px 8px",marginBottom:4}}>CBHI Selector</div>
          {CBHIS.map(c=>(
            <SidebarBtn key={c.id} active={activeCbhi===c.id} onClick={()=>setActiveCbhi(c.id)}
              title={c.name.replace(" CBHI","")} sub={c.active?`${c.members} members`:"Stage: "+(c.stage==="survey_pending"?"Survey Pending":"Premium Design")}/>
          ))}
        </div>
        <div style={{flex:1}}/>
        <div style={{padding:"12px 8px",borderTop:"1px solid rgba(255,255,255,0.08)"}}>
          <button onClick={()=>setPage("landing")} style={{width:"100%",textAlign:"left",padding:"8px 10px",background:"transparent",border:"none",color:"rgba(255,255,255,0.45)",cursor:"pointer",fontSize:12,fontFamily:"inherit"}}>Sign Out</button>
        </div>
      </aside>

      <main style={{flex:1,overflowX:"hidden"}}>
        {/* Tab bar */}
        <div style={{background:C.white,borderBottom:`1px solid ${C.border}`,padding:"0 32px",display:"flex",height:52,position:"sticky",top:0,zIndex:10}}>
          {tabs.map(t=>(
            <TabBtn key={t} label={t} active={activeTab===t} onClick={()=>setActiveTab(t)}/>
          ))}
        </div>

        <div style={{padding:"28px 32px"}}>
          {activeTab==="overview" && <AdminOverview/>}
          {activeTab==="maps & analytics" && <AdminMaps expandedChart={expandedChart} setExpandedChart={setExpandedChart} chartInfo={chartInfo}/>}
          {activeTab==="members" && <AdminMembers/>}
          {activeTab==="claims" && <AdminClaims/>}
          {activeTab==="cbhi management" && <AdminCbhiMgmt/>}
        </div>
      </main>
    </div>
  );
};

const SidebarBtn = ({active,onClick,title,sub}) => {
  const [hov,setHov]=useState(false);
  return (
    <button onClick={onClick} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{width:"100%",textAlign:"left",padding:"8px 10px",borderRadius:8,background:active?"rgba(237,27,46,0.15)":hov?"rgba(255,255,255,0.05)":"transparent",border:active?"1px solid rgba(237,27,46,0.3)":"1px solid transparent",color:active?C.white:"rgba(255,255,255,0.55)",cursor:"pointer",marginBottom:2,fontSize:13,fontFamily:"inherit",transition:"all 0.15s"}}>
      <div style={{fontWeight:active?600:400}}>{title}</div>
      <div style={{fontSize:10,marginTop:2,color:"rgba(255,255,255,0.4)"}}>{sub}</div>
    </button>
  );
};

const TabBtn = ({label,active,onClick}) => {
  const [hov,setHov]=useState(false);
  return (
    <button onClick={onClick} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{background:"transparent",border:"none",borderBottom:active?`2.5px solid ${C.pru}`:"2.5px solid transparent",color:active?C.navy:hov?C.slate:C.muted,cursor:"pointer",padding:"0 16px",height:52,fontSize:13,fontWeight:active?700:400,textTransform:"capitalize",fontFamily:"inherit",transition:"color 0.15s"}}>
      {label}
    </button>
  );
};

