const ChartCard = ({chart,expanded,onToggle,detail}) => {
  const [hov,setHov]=useState(false);
  return (
    <div onClick={onToggle} onMouseEnter={()=>setHov(true)} onMouseLeave={()=>setHov(false)}
      style={{background:C.white,border:`1px solid ${expanded?C.pru:hov?"rgba(237,27,46,0.3)":C.border}`,borderRadius:14,padding:"20px 24px",cursor:"pointer",transition:"border-color 0.2s, box-shadow 0.15s",boxShadow:hov?"0 4px 16px rgba(0,0,0,0.08)":"none"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
        <h3 style={{color:C.navy,margin:0,fontSize:14}}>{chart.title}</h3>
        <span style={{fontSize:11,color:C.pru}}>{expanded?"Close":"Click to read"}</span>
      </div>
      <MiniBar data={chart.data} colors={chart.colors}/>
      {expanded&&(
        <div style={{marginTop:16,paddingTop:16,borderTop:`1px solid ${C.border}`}}>
          <div style={{fontSize:11,fontWeight:700,color:C.pru,textTransform:"uppercase",letterSpacing:0.5,marginBottom:6}}>Interpretation</div>
          <p style={{fontSize:13,color:C.navy,lineHeight:1.75,margin:0}}>{detail}</p>
        </div>
      )}
    </div>
  );
};

